package $package$.domain

import cats.syntax.all._
import sttp.tapir.{Codec, CodecFormat, DecodeResult, Schema}

import java.util.UUID

/** Opaque $domain_name$ identifier, parsed once at the HTTP boundary (parse,
  * don't validate - scala-fp.md law 5). Generated by the shared template so
  * inner layers never accept raw String ids or collapse malformed input into
  * "not found".
  */
opaque type $domain_name;format="cap"$Id = UUID

object $domain_name;format="cap"$Id {

  def parse(raw: String): Either[String, $domain_name;format="cap"$Id] =
    Either
      .catchOnly[IllegalArgumentException](UUID.fromString(raw))
      .leftMap(_ => s"Invalid $domain_name$ id: '\$raw'")

  def fromUuid(value: UUID): $domain_name;format="cap"$Id = value

  def uuid(value: $domain_name;format="cap"$Id): UUID = value

  def render(value: $domain_name;format="cap"$Id): String = value.toString

  given Codec[String, $domain_name;format="cap"$Id, CodecFormat.TextPlain] =
    Codec.string.mapDecode(raw =>
      parse(raw) match {
        case Right(id) => DecodeResult.Value(id)
        case Left(msg) =>
          DecodeResult.Error(raw, new IllegalArgumentException(msg))
      }
    )(render)

  given Schema[$domain_name;format="cap"$Id] =
    Schema.string[$domain_name;format="cap"$Id]
}
